insert into public.notas_paroquia (paroquia_id, texto, fontes, confianca) values
  ('66609a64-48ad-5aab-9108-3eade628c1ef', 'A paróquia da Catedral reúne a Catedral, a Matriz N. Sra. do Carmo (igreja histórica, padroeira da cidade) e a comunidade Menino Jesus. Sem horário semanal publicado; os fiéis mandam depois.', '{"https://diocesederoraima.org.br/","https://diocesederoraima.org.br/igrejas-catolicas-de-boa-vista-celebram-o-natal-com-programacao-especial-de-missas/","https://diocesederoraima.org.br/quarta-feiras-de-cinzas-marca-inicio-do-tempo-quaresmal-para-os-cristaos-catolicos/"}', 'alta'),
  ('1991de62-aa7c-5097-a2e4-9a36e30a537a', 'Sem horário semanal publicado; os fiéis mandam depois.', '{"https://diocesederoraima.org.br/igrejas-catolicas-de-boa-vista-celebram-o-natal-com-programacao-especial-de-missas/","https://diocesederoraima.org.br/diocese-de-roraima-divulga-programacao-da-semana-santa-2025-com-celebracoes-em-boa-vista-e-no-interior/"}', 'alta'),
  ('dd5d3bab-e473-590e-b6b1-71752965fa4a', 'Missas de domingo citadas pela diocese como os horários habituais (7h, 9h30 e 19h30). Igreja jubilar; a 3ª igreja mais antiga de Boa Vista.', '{"https://diocesederoraima.org.br/festa-de-sao-francisco-das-chagas-2026-tera-programacao-especial-em-sintonia-com-o-ano-jubilar-franciscano/","https://diocesederoraima.org.br/igrejas-catolicas-de-boa-vista-celebram-o-natal-com-programacao-especial-de-missas/","https://diocesederoraima.org.br/diocese-de-roraima-divulga-programacao-da-semana-santa-2025-com-celebracoes-em-boa-vista-e-no-interior/"}', 'alta'),
  ('bb306412-021c-5838-b355-a6e1b922fff2', 'Sem horário semanal publicado; os fiéis mandam depois.', '{"https://diocesederoraima.org.br/quarta-feiras-de-cinzas-marca-inicio-do-tempo-quaresmal-para-os-cristaos-catolicos/","https://diocesederoraima.org.br/diocese-de-roraima-divulga-programacao-da-semana-santa-2025-com-celebracoes-em-boa-vista-e-no-interior/"}', 'alta'),
  ('0ec7de10-3ca0-547b-bebb-ed53ba3bfd2e', 'Reitoria (não é paróquia). O Instagram veio do crédito de foto da Folha BV, visto no trecho da busca, não confirmado no perfil. Missas de festa documentadas; o horário semanal não está publicado.', '{"https://diocesederoraima.org.br/festa-de-nossa-senhora-aparecida-sera-celebrada-de-2-a-12-de-outubro-em-boa-vista/","https://www.folhabv.com.br/cotidiano/romaria-e-celebracoes-marcam-festa-de-nossa-senhora-aparecida-em-boa-vista-neste-fim-de-semana/"}', 'alta'),
  ('7dfde78a-fe39-55b9-9758-a15999aee316', 'Instituída em 12/4/2023. A sede é a comunidade São Bento, no bairro Liberdade. Sem horário semanal publicado; os fiéis mandam depois.', '{"https://diocesederoraima.org.br/diocese-de-roraima-institui-tres-novas-paroquias/","https://diocesederoraima.org.br/quarta-feiras-de-cinzas-marca-inicio-do-tempo-quaresmal-para-os-cristaos-catolicos/","https://diocesederoraima.org.br/igreja-celebra-a-imaculada-conceicao-de-maria-neste-8-de-dezembro-veja-programacao-em-boa-vista/","https://diocesederoraima.org.br/igreja-catolica-celebra-solenidade-de-corpus-christi-nesta-quinta-feira-04-confira-a-programacao-na-diocese-de-roraima/"}', 'alta'),
  ('765b5986-0958-50c1-8c0d-b63df5d0ccc8', 'Conhecida como Paróquia Frei Galvão. Instituída em 13/4/2023, com sede na comunidade Bom Pastor. Sem horário semanal publicado; os fiéis mandam depois.', '{"https://diocesederoraima.org.br/diocese-de-roraima-institui-tres-novas-paroquias/","https://diocesederoraima.org.br/igrejas-catolicas-de-boa-vista-celebram-o-natal-com-programacao-especial-de-missas/","https://diocesederoraima.org.br/festa-do-protetor-das-gargantas-e-celebrada-nesta-terca-feira-3/"}', 'alta'),
  ('f815bb18-3f68-57df-8985-6675b249e6b5', 'Instituída em 11/4/2023, com sede na comunidade N. Sra. do Perpétuo Socorro. Sem horário semanal publicado; os fiéis mandam depois.', '{"https://diocesederoraima.org.br/diocese-de-roraima-institui-tres-novas-paroquias/","https://diocesederoraima.org.br/quarta-feiras-de-cinzas-marca-inicio-do-tempo-quaresmal-para-os-cristaos-catolicos/","https://diocesederoraima.org.br/diocese-de-roraima-celebra-missa-em-honra-aos-santos-arcanjos/"}', 'alta'),
  ('8583ae7a-0331-5e1b-b148-120ea1f997b7', 'Cerca de 15 comunidades na zona oeste de Boa Vista (contagem de 2022). Sem horário semanal publicado; os fiéis mandam depois.', '{"https://diocesederoraima.org.br/quarta-feiras-de-cinzas-marca-inicio-do-tempo-quaresmal-para-os-cristaos-catolicos/","https://diocesederoraima.org.br/igreja-catolica-celebra-solenidade-de-corpus-christi-nesta-quinta-feira-04-confira-a-programacao-na-diocese-de-roraima/","https://diocesederoraima.org.br/area-sao-raimundo-nonato-realiza-10a-festa-das-comunidades/"}', 'alta'),
  ('c42c861d-55a9-5f5d-be13-4b6af898355f', 'Zona norte e oeste de Boa Vista. Sem horário semanal publicado; os fiéis mandam depois.', '{"https://diocesederoraima.org.br/quarta-feiras-de-cinzas-marca-inicio-do-tempo-quaresmal-para-os-cristaos-catolicos/","https://diocesederoraima.org.br/igreja-catolica-celebra-solenidade-de-corpus-christi-nesta-quinta-feira-04-confira-a-programacao-na-diocese-de-roraima/","https://diocesederoraima.org.br/diocese-de-roraima-divulga-programacao-da-semana-santa-2025-com-celebracoes-em-boa-vista-e-no-interior/"}', 'alta'),
  ('e3ef93f3-e9c8-5fa3-89a5-8e7a15d1cc35', 'Sem horário semanal publicado; os fiéis mandam depois.', '{"https://diocesederoraima.org.br/quarta-feiras-de-cinzas-marca-inicio-do-tempo-quaresmal-para-os-cristaos-catolicos/","https://diocesederoraima.org.br/diocese-de-roraima-divulga-programacao-da-semana-santa-2025-com-celebracoes-em-boa-vista-e-no-interior/","https://diocesederoraima.org.br/comunidades-da-diocese-de-roraima-realizam-festejos-neste-sabado-08/"}', 'alta'),
  ('ae703c9e-9af0-5cac-b866-f2c1f9d9008b', 'A fonte não diz qual comunidade é a sede; a N. Sra. da Piedade recebe as celebrações maiores da área. Sem horário semanal publicado.', '{"https://diocesederoraima.org.br/igrejas-catolicas-de-boa-vista-celebram-o-natal-com-programacao-especial-de-missas/","https://diocesederoraima.org.br/comunidades-da-diocese-de-roraima-realizam-festejos-neste-sabado-08/"}', 'alta'),
  ('068faf52-c4d0-54bd-b46b-fa093cf23b0f', 'Zona rural de Boa Vista. O site da diocese a lista entre as áreas, com a página aguardando as comunidades enviarem os dados. Sem comunidades nem horários publicados. Ponto no mapa aproximado: centro da cidade.', '{"https://diocesederoraima.org.br/"}', 'media'),
  ('3f4e449b-09df-5519-9abd-6d4bc76200fe', 'Criada em 28/2/1985. Secretaria na Av. João 23, Centro. Atende também comunidades indígenas das regiões Alto Cauamé e Tabaio (11 comunidades listadas pela diocese). Sem horário publicado.', '{"https://diocesederoraima.org.br/alto-alegre/"}', 'alta'),
  ('7a7437d3-a912-591c-8895-99771b5c977b', 'Sem horário semanal publicado; os fiéis mandam depois.', '{"https://diocesederoraima.org.br/","https://diocesederoraima.org.br/diocese-de-roraima-divulga-programacao-da-semana-santa-2025-com-celebracoes-em-boa-vista-e-no-interior/"}', 'alta'),
  ('6c56295a-0231-55b9-bdd6-1cac5750a953', 'Atende Caracaraí e Iracema: 25 comunidades (sede, rurais, ribeirinhas do Baixo Rio Branco e Iracema), das quais 8 estão listadas aqui. Sem horário semanal publicado.', '{"https://diocesederoraima.org.br/caracarai-e-iracema/","https://diocesederoraima.org.br/diocese-de-roraima-divulga-programacao-da-semana-santa-2025-com-celebracoes-em-boa-vista-e-no-interior/"}', 'alta'),
  ('c5394a01-6dbf-55bc-b71c-c7e4c01bf5fe', '27 comunidades urbanas e de vicinais, da Vila Novo Paraíso à Vila Jundiá; 9 listadas aqui. Secretaria na Av. Doutora Yandara, 597. Sem horário semanal publicado.', '{"https://diocesederoraima.org.br/rorainopolis/","https://diocesederoraima.org.br/igreja-catolica-celebra-solenidade-de-corpus-christi-nesta-quinta-feira-04-confira-a-programacao-na-diocese-de-roraima/"}', 'alta'),
  ('b70eed6f-cbd4-59bb-83b7-4c4808a26feb', 'Criada em 10/3/1983. Dois setores: São João Batista (São João da Baliza) e São Luiz. Secretaria na Av. São Paulo, 2580, Centro, São João da Baliza. A página da diocese não traz data; as celebrações podem ser com ou sem padre. Fora do formato: A fonte dá só a hora (8h), sem o dia da semana; A fonte dá só a hora (17h), sem o dia da semana; A fonte dá só a hora (19h), sem o dia da semana; A fonte dá só a hora (10h), sem o dia da semana; A fonte dá só a hora (8h), sem o dia da semana', '{"https://diocesederoraima.org.br/sao-luiz-e-sao-joao-da-baliza/","https://diocesederoraima.org.br/sao-luiz-e-sao-joao-da-baliza/"}', 'media'),
  ('bd8845c0-77b1-5192-a1b5-f015b83ab074', 'Atendida por missionários da Diocese de Jundiaí. A página da diocese está sem conteúdo; comunidades e horários não publicados. Ponto no mapa aproximado: centro da cidade.', '{"https://diocesederoraima.org.br/","https://diocesederoraima.org.br/missa-de-posse-do-pe-samuel-maciel-romao-missionario-da-diocese-de-jundiai-sp-como-paroco-da-area-missionaria-de-santo-isidoro/"}', 'media'),
  ('c0185c8a-7e40-5a39-982e-5ea7db8b67aa', '26 comunidades nos setores Cantá e Félix Pinto; 7 listadas aqui. A fonte não diz qual comunidade é a sede. Sem horário publicado. Ponto no mapa aproximado: centro da cidade.', '{"https://diocesederoraima.org.br/canta/"}', 'alta'),
  ('41b88447-c6b0-507a-8331-aad8dc448042', 'O site da diocese a lista no menu, com a página em desenvolvimento. Comunidades e horários não publicados. Ponto no mapa aproximado: centro da cidade.', '{"https://diocesederoraima.org.br/"}', 'media'),
  ('0bc75717-b75e-5057-96d7-8b4da15a207d', 'O pároco foi afastado em outubro de 2025; a página da diocese está sem conteúdo. Sem horário publicado. Ponto no mapa aproximado: centro da cidade.', '{"https://diocesederoraima.org.br/","https://www.folhabv.com.br/?p=573608"}', 'alta'),
  ('dd172a39-e5d0-53c4-b95a-c6a69a9a60e8', 'Abrange Pacaraima e Amajari. Padres das dioceses de Pádua e Treviso tomaram posse em agosto de 2026. A fonte cita só a comunidade Sagrado Coração de Jesus, em Pacaraima; a sede não está confirmada. Sem horário publicado. Ponto no mapa aproximado: centro da cidade.', '{"https://diocesederoraima.org.br/","https://diocesederoraima.org.br/diocese-de-roraima-celebra-jubileu-dos-migrantes-em-pacaraima/","https://diocesederoraima.org.br/diocese-de-roraima-celebra-posse-de-dois-padres-missionarios/"}', 'media'),
  ('b3018cb9-8564-5c8c-9f4b-efb257577182', 'Missão indígena do Surumu, na Terra Indígena Raposa Serra do Sol. Fundada como missão São José em 1949; criada paróquia em 17/3/1966. 18 comunidades eclesiais nos centros Barro, Cantagalo e Pedreira; 4 listadas aqui. Sem horário publicado. Ponto no mapa aproximado: centro da cidade.', '{"https://diocesederoraima.org.br/surumu/"}', 'alta'),
  ('18557aaf-c5f0-5db0-b442-8bb8db474e79', 'Missão indígena com 26 comunidades wapichana e macuxi nos municípios de Bonfim e Cantá, em 4 blocos (Jacamim, Moscou, Manoá Pium e Malacacheta); 4 listadas aqui. A fonte não aponta sede. Sem horário publicado. Ponto no mapa aproximado: centro da cidade.', '{"https://diocesederoraima.org.br/serra-da-lua/"}', 'alta'),
  ('36c5f149-0647-5406-8c9c-025877603f7e', 'Missão indígena na Terra Indígena Raposa Serra do Sol, região da Raposa: 35 comunidades em 7 blocos; 4 com igreja listadas aqui. A fonte não aponta sede. Sem horário publicado. Ponto no mapa aproximado: centro da cidade.', '{"https://diocesederoraima.org.br/raposa/"}', 'alta'),
  ('da7188e4-efdf-5feb-8219-2aeb3a32039b', 'Missão indígena das Serras, Terra Indígena Raposa Serra do Sol: 84 comunidades indígenas e 65 comunidades eclesiais em 6 centros (Maturuca, Willimon, Morro, Caracanã, Pedra Preta e Caraparu); 5 listadas aqui. Sem horário publicado. Ponto no mapa aproximado: centro da cidade.', '{"https://diocesederoraima.org.br/maturuca/"}', 'alta'),
  ('658479e3-a747-5127-9fe7-86dfdb5489d8', 'Missão indígena nas regiões do Murupu e da Terra Indígena São Marcos, nos municípios de Boa Vista e Pacaraima; 6 das comunidades eclesiais listadas aqui. A fonte não aponta sede. Sem horário publicado. Ponto no mapa aproximado: centro da cidade.', '{"https://diocesederoraima.org.br/sao-marcos-e-murupu/"}', 'alta'),
  ('39adbdfe-0726-5e19-b23c-a0999d3e088b', 'Missão da Consolata junto ao povo Yanomami, no rio Catrimani, Terra Indígena Yanomami, município de Caracaraí; fundada em 1965. A diocese lista 24 comunidades indígenas, sem igrejas. Sem horário publicado. Ponto no mapa aproximado: centro da cidade.', '{"https://diocesederoraima.org.br/catrimani/"}', 'alta')
